// 个人插件 = 本插件（dsh-fish-soul）上自己打的补丁，不是 DSH 里装的插件
function InstalledPlugins() {
	const [data, setData] = react.useState(null);
	const [error, setError] = react.useState(null);
	const [busy, setBusy] = react.useState(false);
	const load = react.useCallback(async () => {
		setBusy(true);
		const r = await api("GET", "/plugins/installed");
		setBusy(false);
		if (r?.ok) { setData(r); setError(null); } else setError(r?.error ?? "清单读不出来");
	}, []);
	react.useEffect(() => { load(); }, [load]);
	if (!data) return error ? h("div", { className: "fs-notice", role: "alert" }, h("b", null, "清单加载失败"), h("span", null, error), Button({ variant: "secondary", onClick: load }, "重试")) : h("div", { className: "fs-empty" }, Dot("ongoing"));
	const KIND = { official: "官方", third: "社区", local: "本地" };
	const STATE = { patched: "已打", upstream: "上游已接管", todo: "没打", missing: "文件不在" };
	const plugins = Array.isArray(data.plugins) ? data.plugins : [];
	const personal = data.personal ?? null;
	const groups = Array.isArray(personal?.groups) ? personal.groups : [];
	const patches = personal ? Group({ title: "个人插件（dsh-fish-soul 的补丁）", aside: h("span", { className: "fs-group-aside" }, `${personal.done}/${personal.total} 处已打${personal.todo > 0 ? ` · ${personal.todo} 处没打` : ""}${personal.version ? ` · v${personal.version}` : ""}`, Button({ variant: "ghost", onClick: load, disabled: busy }, busy ? "读取中…" : "刷新")) },
		h("p", { className: "fs-row-meta" }, "这里的「个人插件」指的是在 dsh-fish-soul 里自己打的补丁，不是 DSH 里安装的插件。每处按它留在源码里的标记核对；上游原生把这件做好了，补丁就会自动退役，状态显示「上游已接管」。"),
		h("div", { className: "fs-list" }, groups.map((g) => h("div", { className: "fs-item", key: g.key },
			h("span", { className: cx("fs-item-main", g.done === g.total && "fs-muted") }, `${g.key} · ${g.name}`),
			h("span", { className: "fs-item-meta" },
				Tag(`${g.done}/${g.total}`, g.done === g.total ? "success" : "outline", { title: g.items.map((x) => `${STATE[x.state] ?? x.state} · ${x.title}`).join("\n") }))))) ,
		h("p", { className: "fs-row-meta" }, "补丁按锚点打，幂等：重复跑只补没打上的，不动别的；上游改版挪了代码会报「漂移」，不会硬改。")) : null;
	const dsh = Group({ title: "DSH 侧插件（对照）", aside: h("span", { className: "fs-group-aside" }, `${plugins.length} 个 · 启用 ${data.enabled ?? 0} 个`) },
		h("p", { className: "fs-row-meta" }, "上面那份是补丁；这一份才是 DSH 里装着的插件，放这里只为对照，别把两者当成一回事。"),
		h("div", { className: "fs-list" }, plugins.map((x) => h("div", { className: "fs-item", key: x.name },
			h("span", { className: cx("fs-item-main", x.enabled === false && "fs-muted") }, x.name),
			h("span", { className: "fs-item-meta" },
				x.self ? Tag("本插件", "outline") : null,
				Tag(`${KIND[x.kind] ?? "其他"}${x.version ? ` ${x.version}` : ""}`, x.enabled ? "success" : "outline"),
				x.enabled ? null : Tag("未启用", "outline", { title: "装在依赖里，但没列进 profile 的 bundles，宿主不会加载" }))))),
		h("p", { className: "fs-row-meta" }, `profile：${data.profile ?? ""} · 只读清单；要装要卸走 dshmarket`));
	return h("div", { className: "fs-plugins-pane" }, patches, dsh);
}

